template <typename UInt> struct write_int_arg {
  UInt abs_value;
  unsigned prefix;

  // Writes a decimal integer with digit grouping.
  template <typename OutputIt, typename Char>
  auto write_int(OutputIt out, unsigned prefix,
                 const format_specs<Char>& specs,
                 const digit_grouping<Char>& grouping) const -> OutputIt {
    auto value = static_cast<uint64_or_128_t<UInt>>(abs_value);
    int num_digits = count_digits(value);
    auto buffer = memory_buffer();
    if (buffer.capacity() < static_cast<size_t>(num_digits))
      buffer.try_reserve(static_cast<size_t>(num_digits));
    format_decimal<char>(appender(buffer), value, num_digits);
    auto digits = string_view(buffer.data(), buffer.size());

    int separator_count = 0;
    if (!grouping.separator().empty()) {
      const auto& groups = grouping.grouping();
      int pos = 0;
      auto group = groups.begin();
      while (true) {
        if (group == groups.end()) {
          if (groups.empty()) break;
          pos += groups.back();
        } else if (*group <= 0 || *group == max_value<char>()) {
          break;
        } else {
          pos += *group++;
        }
        if (num_digits <= pos) break;
        ++separator_count;
      }
    }

    unsigned size =
        to_unsigned((prefix != 0 ? 1 : 0) + static_cast<int>(digits.size()) +
                    separator_count);
    unsigned spec_width = to_unsigned(specs.width);
    size_t padding = spec_width > size ? spec_width - size : 0;
    auto* shifts = "\x00\x1f\x00\x01";
    size_t left_padding = padding >> shifts[specs.align];
    size_t right_padding = padding - left_padding;
    auto fill_size = specs.fill.size();
    auto fill_data = specs.fill.data();
    auto it = reserve(out, size + padding * fill_size);
    auto apply_fill = [&](size_t count) {
      if (count == 0) return;
      if (fill_size == 1) {
        it = detail::fill_n(it, count, fill_data[0]);
      } else {
        for (size_t i = 0; i < count; ++i)
          it = copy_str<Char>(fill_data, fill_data + fill_size, it);
      }
    };
    apply_fill(left_padding);
    if (prefix != 0) {
      char sign = static_cast<char>(prefix);
      *it++ = static_cast<Char>(sign);
    }
    it = grouping.apply(
        it, basic_string_view<char>(digits.data(), digits.size()));
    apply_fill(right_padding);
    return base_iterator(out, it);
  }
};

template <typename T>
FMT_CONSTEXPR auto make_write_int_arg(T value, sign_t sign)
    -> write_int_arg<uint32_or_64_or_128_t<T>> {
  auto prefix = 0u;
  auto abs_value = static_cast<uint32_or_64_or_128_t<T>>(value);
  if (is_negative(value)) {
    prefix = 0x01000000 | '-';
    abs_value = 0 - abs_value;
  } else {
    constexpr const unsigned prefixes[4] = {0, 0, 0x1000000u | '+',
                                            0x1000000u | ' '};
    prefix = prefixes[sign];
  }
  return {abs_value, prefix};
}

template <typename Char = char> struct loc_writer {
  buffer_appender<Char> out;
  const format_specs<Char>& specs;
  std::basic_string<Char> sep;
  std::string grouping;
  std::basic_string<Char> decimal_point;

  template <typename T, FMT_ENABLE_IF(is_integer<T>::value)>
  auto operator()(T value) -> bool {
    auto arg = make_write_int_arg(value, specs.sign);
    arg.write_int(out, arg.prefix, specs,
                  digit_grouping<Char>(grouping, sep));
    return true;
  }

  template <typename T, FMT_ENABLE_IF(!is_integer<T>::value)>
  auto operator()(T) -> bool {
    return false;
  }
};

template <typename Char, typename OutputIt, typename T>
FMT_CONSTEXPR FMT_INLINE auto write_int(OutputIt out, write_int_arg<T> arg,
                                        const format_specs<Char>& specs,
                                        locale_ref) -> OutputIt {
  static_assert(std::is_same<T, uint32_or_64_or_128_t<T>>::value, "");
  auto abs_value = arg.abs_value;
  auto prefix = arg.prefix;
  switch (specs.type) {
  case presentation_type::none:
  case presentation_type::dec: {
    auto num_digits = count_digits(abs_value);
    return write_int(
        out, num_digits, prefix, specs, [=](reserve_iterator<OutputIt> it) {
          return format_decimal<Char>(it, abs_value, num_digits).end;
        });
  }
  case presentation_type::hex_lower:
  case presentation_type::hex_upper: {
    bool upper = specs.type == presentation_type::hex_upper;
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'X' : 'x') << 8 | '0');
    int num_digits = count_digits<4>(abs_value);
    return write_int(
        out, num_digits, prefix, specs, [=](reserve_iterator<OutputIt> it) {
          return format_uint<4, Char>(it, abs_value, num_digits, upper);
        });
  }
  case presentation_type::bin_lower:
  case presentation_type::bin_upper: {
    bool upper = specs.type == presentation_type::bin_upper;
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'B' : 'b') << 8 | '0');
    int num_digits = count_digits<1>(abs_value);
    return write_int(out, num_digits, prefix, specs,
                     [=](reserve_iterator<OutputIt> it) {
                       return format_uint<1, Char>(it, abs_value, num_digits);
                     });
  }
  case presentation_type::oct: {
    int num_digits = count_digits<3>(abs_value);
    // Octal prefix '0' is counted as a digit, so only add it if precision
    // is not greater than the number of digits.
    if (specs.alt && specs.precision <= num_digits && abs_value != 0)
      prefix_append(prefix, '0');
    return write_int(out, num_digits, prefix, specs,
                     [=](reserve_iterator<OutputIt> it) {
                       return format_uint<3, Char>(it, abs_value, num_digits);
                     });
  }
  case presentation_type::chr:
    return write_char(out, static_cast<Char>(abs_value), specs);
  default:
    throw_format_error("invalid format specifier");
  }
  return out;
}
